const assert = require('node:assert/strict')
const { spawnSync } = require('node:child_process')
const { mkdtempSync, writeFileSync, rmSync } = require('node:fs')
const path = require('node:path')
const { test, before, after } = require('node:test')

const root = path.resolve(__dirname, '..')
let fixtureDir
let files
before(() => {
  fixtureDir = mkdtempSync(path.join(root, '.wordcount-test-'))
  files = ['hello world\nnext', '', ' \t\n', '你好 café 😀\n'].map((text, index) => {
    const file = path.join(fixtureDir, `${index}.txt`)
    writeFileSync(file, text)
    return file
  })
})
after(() => {
  if (fixtureDir) rmSync(fixtureDir, { recursive: true })
})

function run(args) {
  return spawnSync(process.execPath, ['index.js', ...args], { cwd: root, encoding: 'utf8' })
}
function output(args, expected) {
  const result = run(args)
  assert.equal(result.error, undefined)
  assert.equal(result.status, 0, result.stderr)
  assert.equal(result.stderr, '')
  assert.equal(result.stdout, expected)
}

test('selection: lines and words print only the selected counts', () => {
  output(['--lines', files[0]], '2\n')
  output([files[0], '--words'], '3\n')
  output(['--words', files[0], '--lines'], '2\t3\n')
  output(['--lines', '--lines', files[0]], '2\n')
})

test('selection: multiple files and edge cases preserve counting rules', () => {
  output(['--lines', ...files], '2\n0\n2\n2\n')
  output([...files, '--words'], '3\n0\n0\n3\n')
})

test('selection: JSON keeps file metadata and only selected count fields', () => {
  for (const [flags, counts] of [
    [['--lines'], { lines: 2 }],
    [['--words'], { words: 3 }],
    [['--words', '--lines'], { lines: 2, words: 3 }],
  ]) {
    const result = run(['--json', ...flags, ...files.slice(0, 2)])
    assert.equal(result.status, 0, result.stderr)
    assert.equal(result.stderr, '')
    assert.deepEqual(JSON.parse(result.stdout), [
      { file: files[0], ...counts },
      { file: files[1], ...Object.fromEntries(Object.keys(counts).map(key => [key, 0])) },
    ])
  }
})

test('default text and JSON output remain unchanged', () => {
  const counts = [[2, 3, 16], [0, 0, 0], [2, 0, 3], [2, 3, 10]]
  output(files, counts.map((row, index) => `${row.join('\t')}\t${files[index]}\n`).join(''))
  const result = run([...files, '--json'])
  assert.equal(result.status, 0, result.stderr)
  assert.deepEqual(JSON.parse(result.stdout), counts.map(([lines, words, characters], index) => ({
    file: files[index], lines, words, characters,
  })))
})

test('missing input files reports usage with exit code 2', () => {
  for (const args of [[], ['--lines'], ['--words'], ['--json', '--lines', '--words']]) {
    const result = run(args)
    assert.equal(result.status, 2)
    assert.equal(result.stdout, '')
    assert.match(result.stderr, /^usage: wordcount .*--lines.*--words/m)
  }
})

